import 'package:flutter/material.dart';
import 'package:lottie/lottie.dart';

import '../../theme/app_colors.dart';

/// The app's Lottie animations (generated by tool/make_lottie.py).
enum BrandAnimationKind {
  goalReached('assets/lottie/goal_reached.json', loop: false, label: 'Goal reached'),
  badgeUnlock('assets/lottie/badge_unlock.json', loop: false, label: 'Badge earned'),
  streakFlame('assets/lottie/streak_flame.json', loop: true, label: 'Streak'),
  walker('assets/lottie/walker.json', loop: true, label: 'Walking figure');

  const BrandAnimationKind(this.asset, {required this.loop, required this.label});
  final String asset;
  final bool loop;
  final String label;
}

/// Plays a brand animation once (celebrations) or on a loop (ambient).
///
/// Respects the system "reduce motion" setting: shows a still frame instead
/// (the final frame of one-shot animations, so the result is still visible).
/// The animation is decorative; [semanticLabel] says what it shows.
class BrandAnimation extends StatefulWidget {
  const BrandAnimation(this.kind, {super.key, this.size = 72, this.semanticLabel});

  final BrandAnimationKind kind;
  final double size;
  final String? semanticLabel;

  @override
  State<BrandAnimation> createState() => _BrandAnimationState();
}

class _BrandAnimationState extends State<BrandAnimation> with SingleTickerProviderStateMixin {
  late final AnimationController _c = AnimationController(vsync: this);

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  void _start(LottieComposition comp) {
    if (!mounted) return;
    _c.duration = comp.duration;
    if (MediaQuery.disableAnimationsOf(context)) {
      _c.value = widget.kind.loop ? 0.3 : 1.0;
    } else if (widget.kind.loop) {
      _c.repeat();
    } else {
      _c.forward(from: 0);
    }
  }

  /// Follows the active colour theme: the walker takes the primary colour,
  /// the goal disc the success colour, and the gold parts the brand gold.
  LottieDelegates _themed(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final brand = Theme.of(context).extension<BrandColors>();
    // Without the app theme (e.g. a bare MaterialApp) keep the file's colours.
    if (brand == null) return const LottieDelegates(values: []);
    return LottieDelegates(values: switch (widget.kind) {
      BrandAnimationKind.walker => [
          ValueDelegate.color(const ['**'], value: scheme.primary),
          ValueDelegate.strokeColor(const ['**'], value: scheme.primary),
        ],
      BrandAnimationKind.goalReached => [
          ValueDelegate.color(const ['disc', '**'], value: brand.success),
        ],
      BrandAnimationKind.badgeUnlock => [
          ValueDelegate.color(const ['star', '**'], value: brand.gold),
          ValueDelegate.strokeColor(const ['ring', '**'], value: brand.gold),
        ],
      BrandAnimationKind.streakFlame => [
          ValueDelegate.color(const ['outer', '**'], value: brand.gold),
        ],
    });
  }

  @override
  Widget build(BuildContext context) {
    return Semantics(
      label: widget.semanticLabel ?? widget.kind.label,
      image: true,
      excludeSemantics: true,
      child: SizedBox.square(
        dimension: widget.size,
        child: Lottie.asset(
          widget.kind.asset,
          controller: _c,
          delegates: _themed(context),
          onLoaded: _start,
          // never let a missing/corrupt asset break the screen
          errorBuilder: (context, error, stack) => const SizedBox.shrink(),
        ),
      ),
    );
  }
}
